<?php require __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';try{$db->beginTransaction();$o=q('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id])->fetch();$allowed=['Unpaid'=>['Paid'],'Paid'=>['Refunded'],'Refunded'=>[]];if(!$o||!isset($allowed[$o['payment_status']])||!in_array($status,$allowed[$o['payment_status']],true)||($o['order_status']==='Cancelled'&&$status==='Paid'))throw new RuntimeException('This payment status transition is not allowed.');q('UPDATE orders SET payment_status=?,updated_at=NOW() WHERE id=?',[$status,$id]);q('UPDATE payments SET status=? WHERE order_id=?',[$status,$id]);q('INSERT INTO notifications(user_id,content) VALUES (?,?)',[$o['user_id'],'Payment for order '.$o['order_number'].' is now '.strtolower($status).'.']);$db->commit();flash('Verified payment status recorded.');}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash($e instanceof PDOException?'Unable to update payment.':$e->getMessage(),'error');}redirect('/admin/payments.php');}$pageTitle='Payments';require __DIR__.'/../includes/admin-start.php';?><div class="page-heading"><h1>Payment records.</h1><p>Mark payments only after verifying receipt or completing a refund outside the store.</p></div><p class="notice">These controls record verified payments. They do not collect money or issue refunds. GCash and bank transfers require merchant payment instructions or a live gateway integration.</p><div class="table-wrap"><table><thead><tr><th>Order</th><th>Method</th><th>Amount</th><th>Status</th><th>Record verified status</th></tr></thead><tbody><?php foreach(q('SELECT p.*,o.order_number FROM payments p JOIN orders o ON o.id=p.order_id ORDER BY p.created_at DESC') as $p):?><tr><td><a href="/admin/order-details.php?id=<?=$p['order_id']?>"><?=e($p['order_number'])?></a></td><td><?=e($p['method'])?></td><td><?=money($p['amount'])?></td><td><?=e($p['status'])?></td><td><form method="post" class="inline-form" data-confirm="Have you independently verified this payment or completed the refund?"><?=csrf()?><input type="hidden" name="id" value="<?=$p['order_id']?>"><select name="status" aria-label="Payment status"><option>Paid</option><option>Refunded</option></select><button class="small-button">Record</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/admin-end.php';?>